using System.Text;

namespace Gojo.Experiments.QualitativeFrieze;

public static partial class CommunicationLoopExperiment
{
    private static string Html(string data) => """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communicate, sample, inspect · Gojo</title><style>
*{box-sizing:border-box}:root{--ink:#27454a;--muted:#637269;--paper:#fbf8ef;--edge:#d6d6c6;--warm:#a96640}body{margin:0;background:#eeeee2;color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:40px 28px 70px}header{max-width:1100px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--warm)}h1{font:clamp(32px,4vw,50px)/1.15 Georgia,serif;margin:12px 0 20px}h2{font:30px/1.2 Georgia,serif;margin:10px 0}h3{font-size:16px;margin:0 0 10px}p{margin:10px 0 16px}.lede{font-size:19px}.nav{display:flex;flex-wrap:wrap;gap:9px;margin:20px 0 30px}a{color:#246a70;text-underline-offset:3px}.nav a{border:1px solid var(--edge);border-radius:20px;padding:6px 13px;background:var(--paper);text-decoration:none;font-size:14px}.legend,.totals{background:#e1e6d9;border-left:3px solid #849465;padding:15px 20px;max-width:1100px;margin:25px 0}.case{margin:45px 0 60px;scroll-margin-top:20px}.case>p{max-width:1050px}.context{max-width:100%;font:14px system-ui;color:var(--ink);padding:10px 14px;background:var(--paper);border:1px solid #a9b29e;margin:5px 0 18px}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.panel{min-width:0;background:var(--paper);border:1px solid var(--edge);padding:20px}.panel img{width:100%;height:auto;display:block}.status{font-size:14px;line-height:1.5;padding:9px 11px;background:#f4e2d6;border-left:3px solid #ba7350;margin:12px 0}.status.pass{border-color:#638068;background:#e7eddf}.support{font-size:14px;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:16px 0 0;border-top:1px solid var(--edge);padding-top:13px}dt{font-size:12px;line-height:1.4;color:var(--muted)}dd{font-size:22px;margin:3px 0}.repair{padding:12px 17px;background:#e9e4d6;font-size:14px;border-left:3px solid #bd9460}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.chip{font-size:12px;line-height:1.4;padding:5px 8px;border:1px solid #d8d7c7;border-radius:12px}.reader details{font-size:13px}details{border-top:1px solid var(--edge);padding:13px 0;margin-top:15px}summary{cursor:pointer}li{margin:7px 0}.footer{font-size:14px;color:var(--muted);border-top:1px solid var(--edge);padding-top:20px}table{border-collapse:collapse;width:100%;font-size:14px;margin:20px 0}th,td{text-align:left;border-bottom:1px solid var(--edge);padding:10px;vertical-align:top}th{font-weight:650}.table-wrap{overflow-x:auto}@media(max-width:950px){.triptych{grid-template-columns:1fr}.panel{padding:16px}.panel img{max-height:300px;object-fit:contain}main{padding:25px 16px}.nav{gap:7px}.nav a{font-size:13px}}
</style></head><body><main><header><span class="eyebrow">Gojo · sparse native communication</span><h1>Say less.<br>Check what survived.</h1><p class="lede">A sender communicates a few structural hints. A receiver selects and executes a more specific construction. A separate reader discovers local patterns in that output, then an evaluator checks the commitments the sender cared about.</p><p>The three examples separate local clues from larger structure: a shared junction, a closed contour, and a connected turning path. Dots mark actual shared sites; hollow marks are endpoints. The pictures show native output after analysis; they are never recognition inputs.</p><nav class="nav"><a href="overview.html">Every run together</a><a href="diagnostics.json">Captured evidence summaries</a><a href="communication.gojo.json.gz">Native evidence archive</a><a href="../junction-interpretations/gallery.html">Junction readings</a></nav></header>
<div class="legend"><strong>The receiver does not know the target.</strong> It receives only the sent pattern hints and an exposed executable library. The reader receives only fresh sites, segments and headings. The evaluator retains the sender's full requirements outside both boundaries.<p>This is a finite-library baseline. The next learned policy could choose which hint to send, ask for, or withdraw.</p></div><div class="totals" id="totals"></div><div id="cases"></div><details><summary>What the evidence establishes</summary><ul id="limits"></ul><p>Required and forbidden pattern clauses are separate native scopes. An omitted hint remains unspecified. Matching retains role and segment correspondences into actual output occurrences; text names do not supply the answer.</p></details><section><h2>A larger experiment</h2><p>Train a hint-selection policy against several receiver libraries, using these native comparisons as an inspectable evaluator. Hold out construction families, receiver preferences and follow-up questions. Later let a generation policy propose native connection or path edits.</p><div class="table-wrap"><table><thead><tr><th>Policy choice</th><th>Evidence to retain</th><th>Measure separately</th></tr></thead><tbody><tr><td>Send or omit a hint</td><td>Actual reusable pattern and message before/after</td><td>Commitment survival, message participation, remaining alternatives</td></tr><tr><td>Ask or refine</td><td>Unresolved read and exposed service response</td><td>Query work, clarification and repair cost</td></tr><tr><td>Generate or modify</td><td>Acknowledged execution and fresh output observation</td><td>Valid output, held-out reads, behavior under further changes</td></tr></tbody></table></div><p class="support">A structural evaluator can check specified promises directly. It should still preserve competing readings and unresolved work; it cannot certify every aspect of meaning or aesthetic quality.</p></section><footer class="footer"><p id="native-summary"></p><p>Shared libraries and receiver work belong in the cost account. A short message alone is not a compression or speed claim.</p></footer><script id="data" type="application/json">__DATA__</script><script>
'use strict';const model=JSON.parse(document.querySelector('#data').textContent),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const metric=(name,value)=>`<div><dt>${esc(name)}</dt><dd>${esc(value)}</dd></div>`;
function sample(panel,sample){panel.querySelector('img').src=sample.image;panel.querySelector('a').href=sample.image;panel.querySelector('img').alt=sample.name;panel.querySelector('.name').textContent=sample.name;const r=sample.read;panel.dataset.satisfied=String(r.satisfied);panel.querySelector('.status').className='status'+(r.satisfied?' pass':'');panel.querySelector('.status').textContent=r.satisfied?'Sender commitments supported':r.unresolved?'Sender commitments remain unresolved':'A sender commitment did not survive';panel.querySelector('.metrics').innerHTML=metric('Sent pattern hints',sample.sentHints)+metric('Admissible library samples',sample.admissible+' / '+sample.examined)+metric('Supported / refuted / open',`${r.supported} / ${r.refuted} / ${r.unresolved}`)+metric('Reader proposal work',sample.proposalWork);const kinds=new Map();for(const p of sample.patterns){const key=`${p.kind} · ${p.segments} segment${p.segments===1?'':'s'}`;kinds.set(key,(kinds.get(key)||0)+p.occurrences)}panel.querySelector('.chips').innerHTML=[...kinds].map(([k,v])=>`<span class="chip">${esc(k)} × ${v}</span>`).join('');panel.querySelector('.patterns').innerHTML=sample.patterns.map(p=>`<li>${esc(p.kind)} · ${p.segments} segments · ${p.occurrences} occurrence${p.occurrences===1?'':'s'} <code>${esc(p.signature)}</code></li>`).join('');}
for(const item of model.cases){const card=document.createElement('article');card.className='case';card.dataset.case=item.id;card.id=item.id;card.innerHTML=`<span class="eyebrow">${esc(item.id)} · communication experiment</span><h2>${esc(item.name)}</h2><p>${esc(item.description)}</p><label class="support">Receiver context <select class="context" aria-label="${esc(item.id)} receiver context"></select></label><div class="triptych"><section class="panel intent"><h3>1. What the sender cares about</h3><a href="${item.intentImage}"><img src="${item.intentImage}" alt="${esc(item.name)} one illustrative target"></a><p>This is one possible realization, not an exact drawing specification.</p><dl class="metrics">${metric('Retained commitments',item.commitments)+metric('Initially transmitted hints',item.initialHints)}</dl><p class="support">The evaluator retains the full native commitments. Only the smaller message reaches the receiver.</p></section><section class="panel sample before"><h3>2. Sample from the sparse message</h3><a><img></a><p class="name"></p><p class="status"></p><dl class="metrics"></dl><div class="reader"><h3>Independent reader's patterns</h3><div class="chips"></div><details><summary>Inspect every induced pattern family</summary><ul class="patterns"></ul></details></div></section><section class="panel sample after"><h3>3. Sample after one repair</h3><a><img></a><p class="name"></p><p class="status"></p><dl class="metrics"></dl><div class="reader"><h3>Independent reader's patterns</h3><div class="chips"></div><details><summary>Inspect every induced pattern family</summary><ul class="patterns"></ul></details></div></section></div><p class="repair"></p>`;const select=card.querySelector('select');item.trials.forEach((trial,index)=>select.add(new Option(trial.context,String(index))));function update(){const trial=item.trials[Number(select.value)];sample(card.querySelector('.before'),trial.before);sample(card.querySelector('.after'),trial.after);card.querySelector('.repair').textContent=trial.repair;card.dataset.context=select.value}select.addEventListener('change',update);update();document.querySelector('#cases').append(card)}
document.querySelector('#totals').textContent=`${model.cases.length} concepts · ${model.trials} receiver trials · ${model.librarySize} executable library samples. Sender commitments supported before repair: ${model.beforeSatisfied}/${model.trials}; after repair: ${model.afterSatisfied}/${model.trials}.`;
document.querySelector('#limits').innerHTML=model.limits.map(s=>`<li>${esc(s)}</li>`).join('');document.querySelector('#native-summary').textContent=`${model.nativeElements.toLocaleString()} captured native participants · ${model.nativeNumericElements} numeric participants · archive restoration verified.`;
const requested=new URLSearchParams(location.search).get('case');if(requested)document.getElementById(requested)?.scrollIntoView();
for(const item of model.cases){const card=document.querySelector(`article[data-case="${item.id}"]`);card.querySelector('.intent').insertAdjacentHTML('beforeend',`<div class="chips promises">${item.promises.map(p=>`<span class="chip">${esc(p)}</span>`).join('')}</div>`);for(const panel of card.querySelectorAll('.sample')){const hints=document.createElement('p');hints.className='support sent-patterns';panel.querySelector('.name').after(hints)}function hints(){const trial=item.trials[Number(card.querySelector('select').value)];card.querySelector('.before .sent-patterns').textContent=trial.before.sentPatterns.join(' · ');card.querySelector('.after .sent-patterns').textContent=trial.after.sentPatterns.join(' · ')}card.querySelector('select').addEventListener('change',hints);hints();const search=model.ablations.find(a=>a.case===item.id);if(search){const best=search.best[0];card.insertAdjacentHTML('beforeend',`<div class="legend ablation"><strong>Can we now omit earlier hints?</strong><p>We checked all ${search.options} subsets of the available clauses against every admitted library output. The smallest sufficient message uses ${search.minimumHints} hint${search.minimumHints===1?'':'s'}, retains ${best.admissible} samples, and contains ${best.messageParticipants} native participants including its shared frame.</p><p>${best.sentPatterns.map(esc).join(' · ')}</p><details><summary>Inspect all hint subsets</summary><div class="table-wrap"><table><thead><tr><th>Hints sent</th><th>Native message participants</th><th>Admissible outputs</th><th>All admitted outputs satisfy intent?</th></tr></thead><tbody>${search.all.map(o=>`<tr><td>${o.sentPatterns.length?o.sentPatterns.map(esc).join('<br>'):'No hints'}</td><td>${o.messageParticipants}</td><td>${o.admissible}</td><td>${o.robust?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div></details><p class="support">This is exhaustive selection over the supplied clauses and library, rather than a trained policy. Shared library and reconstruction costs are additional.</p></div>`)}}
</script></main></body></html>
""".Replace("__DATA__", data);

    private static string Overview(IReadOnlyList<CaseModel> models)
    {
        var html = new StringBuilder("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Communication loop · every sample</title><style>*{box-sizing:border-box}body{margin:0;background:#eeeee2;color:#27454a;font:15px/1.6 system-ui}main{max-width:1500px;margin:auto;padding:30px}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:38px}.row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}figure{background:#fbf8ef;border:1px solid #d7d6c7;padding:15px;margin:0}img{width:100%;height:auto}a{color:#246a70}article{margin:35px 0 45px}figcaption{font-size:14px}.pass{color:#507155}.fail{color:#a15a3c}@media(max-width:750px){main{padding:20px 15px}.row{grid-template-columns:1fr}}</style></head><body><main><h1>Communication · concrete samples · independent reads</h1><p><a href='gallery.html'>Interactive comparison</a> · <a href='diagnostics.json'>Captured summaries</a></p><p>One illustrative target, a receiver sample from sparse hints, and a sample after one additional hint. Dots mark actual shared sites; hollow markers mark endpoints. Different proportions can satisfy the same partial message.</p>");
        foreach (var item in models)
        foreach (var trial in item.Trials)
        {
            string Figure(SampleModel sample, string heading) => $"<figure><img src='{sample.Image}' alt='{H(sample.Name)}'><figcaption><strong>{H(heading)}</strong> · {H(sample.Name)}<br>{sample.SentHints} sent hints · {sample.Admissible} admissible samples<br><span class='{(sample.Read.Satisfied ? "pass" : "fail")}'>{(sample.Read.Satisfied ? "Sender commitments supported" : "Sender commitment did not survive")}</span></figcaption></figure>";
            html.Append($"<article><h2><a href='gallery.html?case={item.Id}'>{H(item.Id + " · " + item.Name)}</a></h2><p>{H(trial.Context)}</p><div class='row'><figure><img src='{item.IntentImage}' alt='{H(item.Name)}'><figcaption>One example of the sender's intended structure</figcaption></figure>{Figure(trial.Before, "Before")}{Figure(trial.After, "After")}</div><p>{H(trial.Repair)}</p></article>");
        }
        return html.Append("<p><a href='gallery.html'>Inspect discovered pattern families</a> · <a href='communication.gojo.json.gz'>Native evidence archive</a></p></main></body></html>").ToString();
    }
}
